for f in files:
    src = open(f).read().split("\n")
    changed = False
    for i, l in enumerate(src):
        n = l
        if "isinstance(" in l:
            n = re.sub(r"\bint\b", "numbers.Integral", n)
            n = re.sub(r"\bfloat\b", "numbers.Real", n)
            n = n.replace("(numbers.Real, numbers.Integral)", "numbers.Real")
            n = n.replace("(numbers.Integral, numbers.Real)", "numbers.Real")
        elif "(float, int), float" in l:
            n = l.replace("(float, int), float", "numbers.Real, float")
        if n != l:
            src[i] = n
            changed = True
            print(f, i + 1, n.strip())
    if changed:
        txt = "\n".join(src)
        if not re.search(r"^import numbers", txt, re.M):
            lines = txt.split("\n")
            idx = None
            for j, ln in enumerate(lines):
                if ln.startswith("import ") or (
                    ln.startswith("from ") and "__future__" not in ln
                ):
                    idx = j
                    break
            lines.insert(idx, "import numbers")
            txt = "\n".join(lines)
        open(f, "w").write(txt)

